def irr(p,ds,t):
 lo,hi=-.999,3
 for _ in range(100):
  mid=(lo+hi)/2
  pv=sum(d/(1+mid)**(i+1) for i,d in enumerate(ds))+t/(1+mid)**3
  if pv>p:lo=mid
  else:hi=mid
 return (lo+hi)/2
